          status: "active",
          invitedBy: null,
          joinedAt: created,
          lastSeenAt: created,
          createdAt: created,
          updatedAt: created,
        })
        .run();

      return { userId, role: roleSpec.role, index: roleIndex };
    });

    const ownerId = seededUsers[0]?.userId ?? nextId();

